There are n cities and there are roads in between some of the cities. Somehow all the roads are damaged simultaneously. We have to repair the roads to connect the cities again. There is a fixed cost to repair a particular road.Input is in the form of edges {u, v, w} where, u and v are city indices. w is the cost to rebuild the road between u and v. Print out the minimum cost to connect all the cities by repairing roads. Examples: Input: {{1, 2, 1}, {1, 3, 2}, {1, 4, 3}, {1, 5, 4},            {2, 3, 5}, {2, 5, 7}, {3, 4, 6}}Output: 10Explanation: Refer the fig...Citymap with 5 cities and 7 damaged roadInput : {{1, 2, 1}, {1, 3, 1}, {1, 4, 100},            {2, 3, 1}, {4, 5, 2}, {4, 6, 2}, {5, 6, 2}}Output : 106Explanation: Minimum cost to connect all the cities is 106Input: {{1,2,5},{2,4,2},{4,3,1},{1,3,7},{1,4,7},{3,,5,3}}Output: 11Explanation: Minimum cost to connect all the cities is 11[Approach] Using Prim's Algorithm - O(ElogV) Time and O(n) SpaceWe can solve this problem using Prim's Algorithm, which finds the Minimum Spanning Tree (MST) to connect all cities with the minimum repair cost.Steps-by-step approach:Start from any random city (usually city 1).Use a Min-Heap (Priority Queue) to always pick the cheapest edge.Maintain a visited array to keep track of cities included in the MST.Add edges to the MST until all cities are connected and return answer at last.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Function to find the minimum cost to connect all the cities
int findMST(int n, vector<vector<int>>& edges) {
    vector<vector<pair<int, int>>> adj(n + 1); // 1-based indexing

    // Convert edge list to adjacency list (1-based indexing adjustment)
    for (auto& edge : edges) {
        int u = edge[0], v = edge[1], w = edge[2];
        adj[u].push_back({w, v});
        adj[v].push_back({w, u});
    }

    // Min-Heap (Priority Queue) to store {weight, node}
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

    vector<bool> inMST(n + 1, false); // To keep track of included nodes
    pq.push({0, 1});  // Start from node **1** instead of 0
    int mstCost = 0;  // Store MST Cost

    while (!pq.empty()) {
        auto tmp = pq.top(); // Get the node with the smallest weight
        int w = tmp.first;
        int u = tmp.second;
        pq.pop();

        // If the node is already in MST, ignore it
        if (inMST[u]) continue;
        inMST[u] = true;
        mstCost += w; // Add weight to MST cost

        // Process all adjacent nodes
        for (auto& it : adj[u]) {

            int weight = it.first;
            int v = it.second;

            if (!inMST[v]) {
                pq.push({weight, v});
            }
        }
    }

    return mstCost;
}

// Driver function
int main() {
    // Input: List of edges {u, v, weight} (1-based indexing)
    vector<vector<int>> city1 = {
        {1, 2, 1}, {1, 3, 2}, {1, 4, 3}, {1, 5, 4},
        {2, 3, 5}, {2, 5, 7}, {3, 4, 6}
    };
    cout <<findMST(5, city1) << endl;

    vector<vector<int>> city2 = {
        {1, 2, 1}, {1, 3, 1}, {1, 4, 100},
        {2, 3, 1}, {4, 5, 2}, {4, 6, 2}, {5, 6, 2}
    };
    cout <<findMST(6, city2) << endl;

    return 0;
}


