    class MinHeap {
    constructor() {
        this.heap = [];
    }

    push(item) {
        this.heap.push(item);
        this.heap.sort((a, b) => a[0] - b[0]); // Min-Heap sorting
    }

    pop() {
        return this.heap.shift(); // Extract min element
    }

    size() {
        return this.heap.length;
    }
}
